const body = $input.first().json.body || $input.first().json;
const cargos = body.cargos || [];
const uploadId = body.upload_id;
const backendUrl = body.backend_url || 'https://shr-backend-prod.onrender.com';

const items = cargos.map(cargo => ({
  json: {
    cargo_id: cargo.id,
    cargo_nombre: cargo.nombre,
    cargo_homologado: cargo.cargo_homologado || '',
    descripcion: cargo.descripcion || '',
    upload_id: uploadId,
    backend_url: backendUrl,
    prompt: `Eres experto en valoración de cargos bajo metodología HAY/SHR.

CARGO: ${cargo.nombre}
HOMOLOGADO: ${cargo.cargo_homologado || 'N/A'}
DESCRIPCIÓN: ${cargo.descripcion || 'N/A'}

Valora usando estos factores (responde SOLO JSON):

Factor 1 - Conocimiento & Habilidad:
- conocimientos: A-H
- experiencia: -/o/+
- habilidad_gerencial: I-VII
- rol_cargo: 1-4

Factor 2 - Comunicación:
- contacto: A/B/C
- frecuencia: 1-4
- contenido_relaciones: I-V

Factor 3 - Solución de Problemas:
- complejidad_conceptual: 1-5
- tendencia_cc: texto breve
- guias_apoyo: A-H
- tendencia_ga: texto breve

Factor 4 - Responsabilidad:
- impacto: I-IV
- autonomia: A-G
- magnitud: 1-14

Criticidad (0 o 1):
- criterio_1, criterio_2, criterio_3

JSON sin explicaciones.`
  }
}));

return items;

const items = [];

for (const item of $input.all()) {
  try {
    const responseBody = item.json;
    const inputData = $('Preparar Valoración').item.json;

    let content = responseBody.choices?.[0]?.message?.content || '';

    if (content.includes('```json')) {
      content = content.split('```json')[1].split('```')[0].trim();
    }

    let result = JSON.parse(content);
    result.cargo_id = inputData.cargo_id;
    result.upload_id = inputData.upload_id;
    result.backend_url = inputData.backend_url;

    items.push({ json: result });
  } catch(e) {
    items.push({
      json: {
        cargo_id: $('Preparar Valoración').item.json.cargo_id,
        error: e.message
      }
    });
  }
}

return items;
